/* Built-in camera, physics, melee and event scripts run in both previews.
 * Board input: touch arrows / SWORD / TALK. Desktop: WASD / Space / E.
 * Override game_on_event to react to ui_melee_hit(game), or add Hit event pages.
 * Audio can be linked with ui_init_with_config(&config); hardware owns I2S/DMA.
 */
#include "ui.h"
void game_on_event(lge_engine_t *g, lge_event_t event, lge_node_t *node, void *user) {
    (void)g; (void)event; (void)node; (void)user;
}
void game_on_update(lge_engine_t *g, float dt, void *user) {
    (void)g; (void)dt; (void)user;
}
